#include <iostream>
#include <memory>

class Query_base {
public:
  virtual ~Query_base() = default;
  virtual void print() = 0;
};

class AndQuery : public Query_base {
public:
  void print() override { std::cout << "AndQuery\n"; }
};

int main() {
  // Using unique_ptr for exclusive ownership
  std::unique_ptr<Query_base> query1 = std::make_unique<AndQuery>();
  query1->print();
  // unique_ptr is automatically deleted when it goes out of scope

  //Example of a potential memory leak without smart pointers
  //Query_base *query2 = new AndQuery(); //Memory leak - requires manual delete
  //query2->print();
  //delete query2; //Manual cleanup needed, prone to error
  return 0;
}
